import json,datetime
a=json.load(open('data/accounts.json'))
def D(p):
    s=datetime.date.fromisoformat(p[0]); e=datetime.date.fromisoformat(p[1]); return (e-s).days+1
def cur(x):
    c=x.get('change')
    if not c: return round(x['base_fee'],2)
    db=c['day']-1; da=30-db
    return round(x['base_fee']*db/30 + c['monthly_fee']*da/30,2)
def fix(x):
    c=x.get('change')
    if not c: return round(x['base_fee'],2)
    d=D(x['period']); db=c['day']-1; da=d-db
    return round(x['base_fee']*db/d + c['monthly_fee']*da/d,2)
diff=[x['id'] for x in a if abs(cur(x)-fix(x))>0.005]
print('accounts where the 30-day hardcode changes the answer:',len(diff))
open('/tmp/pred.txt','w').write('\n'.join(sorted(diff))+'\n')
